// Golden metrics for the NCLT Bengaluru parser on synthetic data (#38, docs/strategy/11 §4): over
// 20 lists generated by seed, a parsed row counts only when every field equals the generator's
// truth. Row precision must be at least 99.5%, recall at least 95% and nested-IA attachment 100%.
// Jittered columns (±3 pt) must parse exactly on every jittered list.
import { describe, expect, it } from 'vitest';

import { NCLT_CONFIG, parseNcltCauseList, type NcltCauseList } from './index.ts';
import {
  generateNcltList,
  randomNcltRecipe,
  type NcltTruth,
  type NcltTruthRow,
} from './synthetic/generate.ts';

const SEEDS = Array.from({ length: 20 }, (_, i) => 38_000 + i);

const truthOf = (row: NcltCauseList['rows'][number]): NcltTruthRow =>
  Object.fromEntries(
    Object.entries(row).filter(([field]) => field !== 'anchor' && field !== 'advocates'),
  ) as NcltTruthRow;
const key = (row: NcltTruthRow) => JSON.stringify(row);

interface Score {
  parsed: number;
  expected: number;
  correct: number;
  nestedExpected: number;
  nestedCorrect: number;
  mismatches: string[];
}

function score(parsed: NcltCauseList, truth: NcltTruth, into: Score): void {
  const expected = new Map(truth.rows.map((row) => [key(row), row]));
  const bySlNo = new Map(
    truth.rows.map((row) => [`${String(row.benchIndex)}:${row.slNo ?? ''}`, row]),
  );
  into.parsed += parsed.rows.length;
  into.expected += truth.rows.length;
  for (const row of parsed.rows) {
    const actual = truthOf(row);
    if (expected.has(key(actual))) {
      into.correct += 1;
    } else {
      const want = bySlNo.get(`${String(row.benchIndex)}:${row.slNo ?? ''}`);
      into.mismatches.push(`got ${key(actual)}\nwant ${want === undefined ? '(none)' : key(want)}`);
    }
  }
  for (const want of truth.rows.filter((row) => row.children.length > 0)) {
    into.nestedExpected += 1;
    const got = parsed.rows.find(
      (row) => row.cp.number === want.cp.number && row.slNo === want.slNo,
    );
    if (got !== undefined && JSON.stringify(got.children) === JSON.stringify(want.children)) {
      into.nestedCorrect += 1;
    }
  }
}

const emptyScore = (): Score => ({
  parsed: 0,
  expected: 0,
  correct: 0,
  nestedExpected: 0,
  nestedCorrect: 0,
  mismatches: [],
});

describe('NCLT golden metrics on synthetic lists', () => {
  it('generates 20 lists deterministically by seed', async () => {
    for (const seed of SEEDS.slice(0, 3)) {
      const a = await generateNcltList(randomNcltRecipe(seed));
      const b = await generateNcltList(randomNcltRecipe(seed));
      expect(JSON.stringify(a)).toBe(JSON.stringify(b));
    }
    const lists = await Promise.all(SEEDS.map((seed) => generateNcltList(randomNcltRecipe(seed))));
    expect(lists).toHaveLength(20);
    expect(new Set(lists.map((list) => JSON.stringify(list.truth))).size).toBe(20);
  });

  it('meets row precision >= 99.5%, recall >= 95% and nested-IA attachment 100%', async () => {
    const total = emptyScore();
    for (const seed of SEEDS) {
      const list = await generateNcltList(randomNcltRecipe(seed));
      score(parseNcltCauseList(list.layout, NCLT_CONFIG), list.truth, total);
    }
    expect(total.mismatches.slice(0, 3)).toEqual([]);
    expect(total.expected).toBeGreaterThan(200);
    expect(total.correct / total.parsed).toBeGreaterThanOrEqual(0.995);
    expect(total.correct / total.expected).toBeGreaterThanOrEqual(0.95);
    expect(total.nestedExpected).toBeGreaterThan(20);
    expect(total.nestedCorrect).toBe(total.nestedExpected);
  });

  it('survives ±3 pt column jitter on every jittered list', async () => {
    for (const seed of SEEDS) {
      const list = await generateNcltList({ ...randomNcltRecipe(seed), jitterPx: 3 });
      const result = emptyScore();
      score(parseNcltCauseList(list.layout, NCLT_CONFIG), list.truth, result);
      expect(result.mismatches, `seed ${String(seed)}`).toEqual([]);
      expect(result.correct, `seed ${String(seed)}`).toBe(list.truth.rows.length);
    }
  });
});
